import os
import hmac
import hashlib
import time
import json
from flask import Flask, request, jsonify, g
import sqlite3
import subprocess

app = Flask(__name__)
DATABASE = '/var/lib/app/reports.db'
SECRET = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_hmac(payload, signature):
    """Verify request authenticity via HMAC-SHA256"""
    expected = hmac.new(SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/reports/generate', methods=['POST'])
def generate_report():
    """Generate PDF report from template with user-specified parameters"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid JSON'}), 400

    report_type = data.get('report_type', 'summary')
    date_range = data.get('date_range', 'last_30d')
    output_format = data.get('format', 'pdf')

    # Validate report_type against allowed values
    allowed_types = ['summary', 'detailed', 'executive', 'compliance']
    if report_type not in allowed_types:
        return jsonify({'error': 'Invalid report type'}), 400

    # Validate date_range format (YYYY-MM-DD_YYYY-MM-DD)
    if date_range != 'last_30d' and date_range != 'last_90d':
        parts = date_range.split('_')
        if len(parts) != 2:
            return jsonify({'error': 'Invalid date range format'}), 400

    # Build the report generation command
    template_dir = '/opt/app/templates'
    output_dir = '/tmp/reports'

    # The output filename is derived from user input
    custom_name = data.get('filename', f'report_{int(time.time())}')

    # Sanitize: remove path separators to prevent directory traversal
    custom_name = custom_name.replace('/', '').replace('\\', '')

    output_path = f"{output_dir}/{custom_name}.{output_format}"

    # Generate report using wkhtmltopdf with template
    template_file = f"{template_dir}/{report_type}.html"

    cmd = f"wkhtmltopdf --quiet --page-size A4 --title '{custom_name}' {template_file} {output_path}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=output_dir
        )
        if result.returncode != 0:
            app.logger.error(f"Report generation failed: {result.stderr.decode()}")
            return jsonify({'error': 'Report generation failed'}), 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Report generation timed out'}), 504

    # Log the generation event
    db = get_db()
    db.execute(
        'INSERT INTO report_log (report_type, date_range, filename, created_at) VALUES (?, ?, ?, ?)',
        (report_type, date_range, custom_name, int(time.time()))
    )
    db.commit()

    return jsonify({
        'status': 'success',
        'download_url': f'/api/reports/download/{custom_name}.{output_format}',
        'expires_in': 3600
    })

@app.route('/api/reports/download/<path:filename>', methods=['GET'])
def download_report(filename):
    """Download a generated report file"""
    filepath = os.path.join('/tmp/reports', os.path.basename(filename))
    if not os.path.exists(filepath):
        return jsonify({'error': 'Report not found'}), 404
    return app.send_static_file(filepath)

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.4.1'})

if __name__ == '__main__':
    os.makedirs('/tmp/reports', exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
